/* updateMasterMpRqBulkQuotationProjectStatus_1 */
UPDATE KEP_BURQ_MNG
SET PROJECT_STATUS = DECODE(SG_START_DATE,NULL,'A',PROJECT_STATUS),
	SG_START_DATE =  DECODE(SG_START_DATE,NULL,SYSDATE,SG_START_DATE),
	TOTAL_ITEM_CNT = (SELECT COUNT(*) FROM KEP_BURQ_ITEM WHERE BURQ_NO = #{st_burq_no}),
	TOTAL_AMT = (SELECT SUM(RE_LIST_PRICE*NVL(ITEM_QTY,1)) FROM KEP_BURQ_ITEM WHERE BURQ_NO = #{st_burq_no}),
	CHANGE_DATE = SYSDATE,
	CHANGE_USER_ID = #{USER_ID}
WHERE BURQ_NO = #{st_burq_no}
